import os
import openai

def safety_threshold(payload, config=None):
    config = config or {}
    api_key = os.getenv("OPENAI_API_KEY")
    client = openai.OpenAI(api_key=api_key)
    text = payload.get("text", "")
    if not text.strip():
        scores = {}
    else:
        response = client.moderations.create(
            model="text-moderation-latest",
            input=text
        )
        moderation = response.results[0]
        scores = moderation.category_scores
    thresholds = config.get("thresholds", {})
    allow = all(scores.get(category, 0.0) <= threshold for category, threshold in thresholds.items())
    result = {"allow": allow, "scores": scores}
    return result
